INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-01','Buck Converter: Output Voltage','Easy','EEE','arena','calculate','Power Electronics','multiple_choice','A buck (step-down) converter has V_in = 12 V and duty cycle D = 0.6 (60%). Assuming ideal operation, what is the output voltage?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-02','Boost Converter: Output Voltage','Easy','EEE','arena','calculate','Power Electronics','multiple_choice','A boost (step-up) converter: V_in = 5 V, duty cycle D = 0.5. Ideal output voltage:
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-03','H-Bridge Motor Drive','Easy','EEE','arena','select','Power Electronics','multiple_choice','An H-bridge circuit controls a DC motor''s direction of rotation by:','{"choices": ["Varying the DC supply voltage", "Switching alternating pairs of transistors — Q1,Q4 closed: forward; Q2,Q3 closed: reverse; all open: coast; all closed: brake (short-circuit motor terminals)", "Using a transformer", "Varying frequency"], "correct": 1}'::jsonb,'H-bridge: 4 switches (transistors) in H-configuration. Diagonal pairs control current direction: (Q1,Q4)→forward current; (Q2,Q3)→reverse current. PWM on one switch controls speed. Critical: never short the supply (shoot-through) by closing both switches in one leg simultaneously.','{multiple_choice}'::text[],0.85) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-04','Diode: Reverse Recovery Time','Easy','EEE','arena','interpret','Power Electronics','multiple_choice','A standard PN diode has a long reverse recovery time (t_rr ≈ 1 µs). This causes problems in switching power supplies because:','{"choices": ["The diode becomes a capacitor during recovery", "During reverse recovery, the diode momentarily conducts in reverse direction — causing current spikes and energy loss that increases switching losses and can damage the switch", "The diode permanently breaks down", "The diode oscillates at 1 MHz"], "correct": 1}'::jsonb,'Reverse recovery: minority carriers stored during forward conduction take time to recombine when reverse voltage is applied. During t_rr, large reverse current flows → creates short circuit on supply through the switch. Solution: Schottky diodes (no minority carrier storage, t_rr ≈ 0) or soft-recovery diodes.','{multiple_choice}'::text[],0.82) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-05','Three-Phase Rectifier: Output Ripple','Easy','EEE','arena','compare','Power Electronics','multiple_choice','A three-phase full-wave rectifier produces less output ripple than a single-phase full-wave rectifier because:','{"choices": ["Three-phase rectifiers use 6 diodes instead of 4", "Three-phase rectifier output has 6 pulses per cycle (six-pulse rectifier) vs 2 pulses per cycle for single-phase — higher pulse number means smaller voltage ripple and higher average output", "Three-phase supplies have higher voltage", "Three-phase rectifiers operate at higher frequency"], "correct": 1}'::jsonb,'Three-phase bridge rectifier: 6 diodes, 6 output pulses per cycle (360°/6=60° ripple period). Ripple frequency = 6 × f_supply = 300 Hz (for 50 Hz). Single-phase: 2 pulses/cycle, 100 Hz ripple. Higher pulse number → smaller ripple → smaller filter needed.','{multiple_choice}'::text[],0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-06','Inductor Current in CCM vs DCM','Medium','EEE','arena','predict','Power Electronics','multiple_choice','A buck converter operating in Discontinuous Conduction Mode (DCM) means:','{"choices": ["Output current is zero", "The inductor current falls to zero during part of the switching cycle — occurs at light load; changes transfer function and dynamic behaviour compared to CCM", "The converter is operating illegally", "The diode is always conducting"], "correct": 1}'::jsonb,'CCM: inductor current never reaches zero — continuous flow. DCM: at light load, inductor current falls to zero → diode turns off → three distinct intervals. DCM: V_out/V_in depends on duty cycle AND load resistance (different from CCM where V_out = D×V_in).','{multiple_choice}'::text[],0.74) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-07','SPWM: Sinusoidal Pulse Width Modulation','Medium','EEE','arena','interpret','Power Electronics','multiple_choice','In SPWM for a single-phase inverter, the fundamental output voltage amplitude is related to the modulation index m_a by:
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-08','Gate Drive Circuit for MOSFET','Medium','EEE','arena','select','Power Electronics','multiple_choice','A gate drive circuit for a high-side MOSFET in a half-bridge requires a bootstrap supply because:','{"choices": ["MOSFETs require higher gate voltage than low-side", "The high-side MOSFET source is connected to the switching node (not ground) — gate voltage must be referenced to the switching node; bootstrap generates a floating supply V_GS = V_BS + V_sw above the switching node", "MOSFETs require negative gate voltage to turn off", "Bootstrap increases switching speed"], "correct": 1}'::jsonb,'High-side N-MOSFET: V_GS needed = V_G − V_S. Since V_S = V_SW (0 to V_dc), V_G must be V_SW + 10–15 V. Bootstrap: capacitor charged to V_BST when low-side is on (V_SW = 0); when high-side switches, capacitor floats up with V_SW, providing floating gate drive.','{multiple_choice}'::text[],0.7) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-09','Flyback Converter Operation','Medium','EEE','arena','interpret','Power Electronics','multiple_choice','A flyback converter is essentially a coupled-inductor boost converter. During the off-time of the main switch:','{"choices": ["The transformer transfers energy from primary to secondary directly", "Energy stored in the coupled inductor (transformer with air gap) during on-time is released to the output through the secondary winding — primary and secondary do not conduct simultaneously (unlike a true transformer)", "The output capacitor charges from the primary supply", "The diode on the secondary turns off"], "correct": 1}'::jsonb,'Flyback: during on-time, primary diode reverse biased → energy stored in magnetic core. During off-time, stored energy transferred to secondary → output. Isolation and multiple outputs possible. Common for < 100 W power supplies (phone chargers, switchers).','{multiple_choice}'::text[],0.68) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-10','Dead Time in Half-Bridge Inverter','Medium','EEE','arena','select','Power Electronics','multiple_choice','Dead time (blanking time) is inserted between the turn-off of one switch and turn-on of the complementary switch in a half-bridge inverter to:','{"choices": ["Increase output voltage", "Improve efficiency", "Prevent shoot-through — simultaneous conduction of both switches would short-circuit the DC bus (V_dc direct to GND), causing catastrophic switch failure", "Reduce EMI"], "correct": 2}'::jsonb,'Shoot-through (cross-conduction): Q_high and Q_low on simultaneously → V_dc across switches → di/dt limited only by stray inductance → massive current surge → device destruction. Dead time: both off simultaneously → freewheeling diodes conduct → no shoot-through. Minimum dead time = switch turn-off time.','{multiple_choice}'::text[],0.76) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-11','Active Power Factor Correction (PFC)','Medium','EEE','arena','select','Power Electronics','multiple_choice','A boost PFC converter in a power supply draws sinusoidal input current in phase with the supply voltage. The benefit is:','{"choices": ["Higher output voltage", "Power factor ≈ 1 (unity) — reduces reactive power drawn from the utility, reduces line current harmonics (THD), meets IEC 61000-3-2 EMC standards, and improves efficiency of the power distribution system", "Lower output voltage ripple", "Simpler control circuitry"], "correct": 1}'::jsonb,'Without PFC: capacitor-input rectifier draws spiky current (PF ≈ 0.5–0.7, THD > 100%). Boost PFC: forces I_in to follow sin wave → PF > 0.99, THD < 5%. Required for equipment > 75 W in Europe (IEC 61000-3-2). Improves utilisation of distribution infrastructure.','{multiple_choice}'::text[],0.72) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-12','Resonant Converter: ZVS and ZCS','Hard','EEE','arena','interpret','Power Electronics','multiple_choice','Resonant converters (LLC, series resonant) achieve higher efficiency than hard-switching converters because:','{"choices": ["They use fewer components", "Zero Voltage Switching (ZVS) or Zero Current Switching (ZCS) — switch transitions occur when voltage or current is zero → no overlap of V and I during switching → zero switching losses; allows higher frequency operation", "They eliminate the output filter", "They operate at lower duty cycles"], "correct": 1}'::jsonb,'Hard switching: V and I both non-zero during transition → P_switch = V × I × t_r × f. Soft switching: ZVS (turn-on when V=0), ZCS (turn-off when I=0) → switching loss → 0. Enables f_sw > 1 MHz for compact magnetics. LLC resonant converter: widely used in PC ATX supplies and EV chargers.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-13','STATCOM vs SVC: Reactive Power','Hard','EEE','arena','compare','Power Electronics','multiple_choice','A STATCOM (Static Compensator) uses a voltage-source inverter while a SVC (Static VAR Compensator) uses thyristor-switched capacitors/inductors. STATCOM advantage:','{"choices": ["STATCOM is cheaper for large installations", "STATCOM can provide rated reactive current even at low system voltage (current-source behaviour), while SVC reactive power output drops with V² — STATCOM maintains support during voltage sags", "STATCOM has lower losses", "SVC has faster response time"], "correct": 1}'::jsonb,'SVC: Q ∝ V² (capacitor/inductor current × voltage). During fault (low V), SVC provides less support. STATCOM: voltage-source converter → constant current → Q ∝ V. Better voltage recovery after fault. Also faster response (< 1 cycle vs SVC thyristor firing delay).','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-14','Solar Inverter: MPPT Algorithm','Hard','EEE','arena','select','Power Electronics','multiple_choice','The Perturb & Observe (P&O) MPPT algorithm in a solar inverter works by:','{"choices": ["Measuring panel temperature and using a lookup table", "Periodically perturbing (increasing/decreasing) the operating voltage and observing change in power — if power increases, continue in same direction; if decreases, reverse direction. Converges to MPP", "Sweeping the full I-V curve every cycle", "Fixed voltage operation at 0.8 × V_oc"], "correct": 1}'::jsonb,'P&O: measure P[k]. Perturb V. Measure P[k+1]. If P[k+1] > P[k] and ΔV > 0 → continue increasing V; if P[k+1] < P[k] and ΔV > 0 → reverse. Oscillates ±1 step around MPP. Under rapidly changing irradiance: can track away from MPP (faster algorithms: Incremental Conductance, FOCV).','{multiple_choice}'::text[],0.68) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-15','Cuk Converter Characteristics','Hard','EEE','arena','compare','Power Electronics','multiple_choice','The Ćuk converter differs from a standard buck-boost converter in that:','{"choices": ["Ćuk converter is only for positive output voltages", "Ćuk converter uses a capacitor as the intermediate energy storage element (vs inductor in standard buck-boost) — provides continuous input and output current (both inductors), lower ripple, but requires two inductors and a capacitor", "Ćuk converter cannot invert polarity", "Ćuk converter is simpler to control"], "correct": 1}'::jsonb,'Ćuk: input inductor L₁, coupling capacitor C₁, output inductor L₂, output capacitor C₂. Transfer ratio: V_out = −D/(1−D) × V_in (inverting, same as standard buck-boost). Advantage: continuous current at both input and output — lower input/output ripple. Disadvantage: more components.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-16','Current-Mode Control vs Voltage-Mode Control','Hard','EEE','arena','compare','Power Electronics','multiple_choice','Peak current-mode control in a switching converter is preferred over voltage-mode control because:','{"choices": ["It eliminates the need for output filter", "Current-mode control provides inherent current limiting (inner current loop), automatic feed-forward of input voltage, simpler compensator design (single-pole response for buck), and better transient response", "It operates at lower switching frequency", "It requires no voltage feedback"], "correct": 1}'::jsonb,'Voltage-mode: compensator must control both L and C poles (two poles). Current-mode: inner current loop creates dominant first-order behaviour (inductor pole cancelled) → single-pole system → easier Type II compensator. Input voltage feed-forward: when V_in changes, inductor current automatically adjusts.','{multiple_choice}'::text[],0.6) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-17','Inductor Selection for Buck Converter','Hard','EEE','arena','calculate','Power Electronics','multiple_choice','A buck converter: V_in=12V, V_out=5V, I_out=2A, f_sw=200kHz. Minimum inductance for CCM operation (ΔI_L ≤ 40% of I_out):
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-18','Interleaved Buck Converter','Hard','EEE','arena','interpret','Power Electronics','multiple_choice','An interleaved buck converter uses N parallel buck stages with phase-shifted clocks. The benefit is:','{"choices": ["N times higher output voltage", "Input and output current ripple frequency multiplies by N (and ripple amplitude reduces) — smaller filter inductors and capacitors needed; also distributes thermal stress across N smaller switches", "N times lower output voltage", "N times higher efficiency always"], "correct": 1}'::jsonb,'Interleaving: N stages, each at f_sw, phased by 360°/N. Effective ripple frequency = N × f_sw. Ripple cancellation: at certain duty cycles, ripple cancels completely (e.g., 2-phase at D=0.5: full cancellation). Allows smaller, faster inductors. Used in processor VRMs (up to 6–16 phases).','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-19','Neutral Point Clamped (NPC) Inverter','Hard','EEE','arena','interpret','Power Electronics','multiple_choice','A 3-level NPC inverter produces three output voltage levels (+V_dc/2, 0, −V_dc/2) instead of two. The advantage for motor drive applications is:','{"choices": ["Higher output current", "Lower THD in output voltage — three levels → smaller output dV/dt → reduced motor insulation stress, lower bearing currents, smaller EMI filter; also allows higher DC bus voltage with standard IGBT voltage rating", "Higher switching frequency", "Simpler gate drive"], "correct": 1}'::jsonb,'Multilevel inverters: N levels → (N−1) steps → lower dV/dt and lower harmonics for same switching frequency. NPC advantage: each switch sees V_dc/2 (not full V_dc) → can use lower voltage IGBTs at high DC voltage. Used in medium-voltage drives (3.3 kV, 6.6 kV) and HVDC.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-20','Bidirectional DC-DC Converter','Hard','EEE','arena','select','Power Electronics','multiple_choice','A bidirectional buck-boost DC-DC converter is used in battery energy storage systems (BESS) because:','{"choices": ["It provides galvanic isolation between battery and DC bus", "It controls power flow in both directions — charging mode (boost from low battery voltage to high DC bus) and discharging mode (buck from DC bus to battery charging) using a single converter with active switching", "It eliminates the need for a battery management system", "It only works with lithium-ion batteries"], "correct": 1}'::jsonb,'Bidirectional converter: switch pair in each leg. Charging: control Q2 (buck operation from bus to battery). Discharging: control Q1 (boost from battery to bus). Current direction reversal by reversing which switch is PWM-controlled. Used in EVs (motor regen + propulsion), BESS, UPS.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-21','Matrix Converter: Direct AC-AC','Hard','EEE','arena','compare','Power Electronics','multiple_choice','A matrix converter is preferred over a back-to-back VSC (rectifier+inverter) for AC drive applications in specific cases because:','{"choices": ["Matrix converter has higher power density always", "Matrix converter provides direct AC-AC conversion without DC link capacitor — no electrolytic capacitor (lifetime concern), true four-quadrant operation, sinusoidal input/output currents. Disadvantage: limited voltage gain (86%), complex modulation", "Matrix converter is cheaper", "Matrix converter has higher efficiency at all power levels"], "correct": 1}'::jsonb,'Matrix converter: 9 bidirectional switches (3-phase in × 3-phase out). Advantages: no DC bus capacitor → longer life, smaller size, bidirectional. Limitation: output V_max = 0.866 × V_in (Alesina-Venturini limit). Complex commutation (no freewheeling path). Used in aerospace, marine applications.','{multiple_choice}'::text[],0.52) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-22','Snubber Circuit for IGBT','Hard','EEE','arena','select','Power Electronics','multiple_choice','An RCD snubber across an IGBT in a hard-switching converter is used to:','{"choices": ["Reduce gate drive current", "Limit the dV/dt across the device during turn-off — the capacitor absorbs energy during switching transition, limiting voltage overshoot from stray inductance (V = L_stray × dI/dt)", "Provide overcurrent protection", "Reduce on-state conduction loss"], "correct": 1}'::jsonb,'Snubber: capacitor C limits dV/dt (charges while IGBT turns off). Resistor R damps resonance and resets C during next on-time. Diode D directs current properly. Without snubber: stray inductance L → voltage spike L×dI/dt can exceed IGBT V_CE(max) → device failure.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-23','DAB (Dual Active Bridge) Converter','Hard','EEE','arena','interpret','Power Electronics','multiple_choice','The Dual Active Bridge (DAB) isolated DC-DC converter achieves bidirectional power transfer by:','{"choices": ["Using two separate converters with a switch matrix", "Controlling the phase shift between the two H-bridge switching waveforms — power flow direction and magnitude determined by phase angle φ: P ∝ sin(φ); φ > 0 → power from primary to secondary; φ < 0 → reverse", "Using a rectifier on one side only", "Operating the bridges at different frequencies"], "correct": 1}'::jsonb,'DAB: H-bridge on each side of HF transformer. Primary and secondary bridges both produce square waves at same frequency f_sw. Phase shift φ between them determines power: P = (V₁ V₂)/(2π f_sw L_r) × φ(1 − φ/π). Bidirectional, soft-switchable. Used in SSTs, EV on-board chargers.','{multiple_choice}'::text[],0.52) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-24','WBG Devices in Power Converters','Hard','EEE','arena','compare','Power Electronics','multiple_choice','SiC MOSFETs replace silicon IGBTs in >600 V EV traction inverters primarily because:','{"choices": ["SiC has lower manufacturing cost", "SiC switches faster with lower switching losses → enables higher switching frequency → smaller magnetics → higher power density; lower conduction losses at high temp (positive R_DS(on) temp coefficient unlike IGBT V_CE(sat))", "SiC devices have lower gate capacitance than silicon MOSFETs", "SiC can operate at lower voltages more efficiently"], "correct": 1}'::jsonb,'SiC MOSFET advantages in EV inverter: t_sw < 50 ns (IGBT: 200–500 ns) → lower switching losses at 10–20 kHz → smaller inverter. R_DS(on) increases with temperature (positive TC): safe paralleling. No tail current. T_j(max) = 200°C → better thermal design. Enables 800 V EV platforms.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('eee-pe-25','Grid-Tied Inverter: Island Detection','Hard','EEE','arena','select','Power Electronics','multiple_choice','Anti-islanding protection in a grid-tied solar inverter is critical because:','{"choices": ["Islanding increases inverter output voltage", "If the grid disconnects (fault, maintenance), an inverter continuing to energise the local island poses electrocution risk to line workers and may damage equipment — the inverter must detect loss of grid and disconnect within 2 seconds (IEEE 1547)", "Islanding reduces solar panel efficiency", "Anti-islanding prevents reverse power flow"], "correct": 1}'::jsonb,'Islanding: inverter + local load separated from grid → continues operating. Danger: line workers assume de-energised but island is live. Detection methods: passive (frequency/voltage deviation), active (frequency shift, Sandia voltage shift), or grid-signal injection. IEEE 1547 mandates detection < 2 s.','{multiple_choice}'::text[],0.65) ON CONFLICT (slug) DO NOTHING;
